#!/bin/sh
# Lints every tracked shell script (any file whose first line is a sh/bash
# shebang): shellcheck, plus shfmt formatting (-i 4 -ci). gradlew is
# generated by Gradle, so it gets shellcheck but is never reformatted.
#
#   scripts/lint-shell.sh        uses shellcheck and shfmt from PATH
#
# CI sets SHELLCHECK and SHFMT to pinned Docker images instead.
set -eu

cd "$(git rev-parse --show-toplevel)"
shellcheck_cmd=${SHELLCHECK:-shellcheck}
shfmt_cmd=${SHFMT:-shfmt}

list=$(mktemp)
trap 'rm -f "$list"' EXIT
# shellcheck disable=SC2016 # $0 belongs to awk, not the shell
git ls-files -z |
    xargs -0 awk 'FNR == 1 { if ($0 ~ /^#!.*[\/ ](sh|bash|dash|ksh)([ \t]|$)/) print FILENAME; nextfile }' >"$list"

# gradlew always exists, so finding nothing means the search itself broke.
count=$(wc -l <"$list")
if [ "$count" -eq 0 ]; then
    echo "lint-shell: found no shell scripts, not even gradlew; the file search is broken" >&2
    exit 1
fi

echo "shellcheck: $count file(s)"
sed 's/^/  /' "$list"
# shellcheck disable=SC2086 # the command may be several words (docker run ...)
tr '\n' '\0' <"$list" | xargs -0 $shellcheck_cmd -x

formatted=$(grep -vx 'gradlew' "$list" || true)
if [ -z "$formatted" ]; then
    echo "shfmt: nothing to check (gradlew is generated, not ours to format)"
    exit 0
fi
echo "shfmt:"
printf '%s\n' "$formatted" | sed 's/^/  /'
# shellcheck disable=SC2086
printf '%s\n' "$formatted" | tr '\n' '\0' | xargs -0 $shfmt_cmd -i 4 -ci -d
echo "lint-shell: all clean"
